sir:
sir 0.3
software Blog {
  metadata { displayName "Blog"; namespace "example.blog"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations {
    enum PostState { DRAFT, PUBLISHED }

    entity User persistent {
      identity id: Id generated auto;
      field name: Name unique;
    }

    entity AccessToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field expiresAt: Moment;
      credential subject owner expires expiresAt;
    }

    entity Category persistent {
      identity id: Id generated auto;
      field name: Code unique;
    }

    entity Post persistent {
      identity id: Id generated auto;
      field author: Ref<User>;
      field category: Ref<Category>;
      field title: Name;
      field content: Text;
      field state: PostState default PostState.DRAFT;
      field likes: Count default 0;
      field createdAt: Moment;
    }

    entity Tag persistent {
      identity id: Id generated auto;
      field name: Code unique;
    }

    entity PostTag persistent {
      identity id: Id generated auto;
      field post: Ref<Post>;
      field tag: Ref<Tag>;
      unique (post, tag);
    }

    entity Like persistent {
      identity id: Id generated auto;
      field post: Ref<Post>;
      field user: Ref<User>;
      unique (post, user);
    }

    view AuthorView from User {
      field id: Id;
      field name: Name;
    }

    view CategoryView from Category {
      field id: Id;
      field name: Code;
    }

    view PublicPost from Post {
      field id: Id;
      field author: AuthorView;
      field category: CategoryView;
      field title: Name;
      field content: Text;
      field likes: Count;
      field createdAt: Moment;
    }

    view PostView from Post {
      field id: Id;
      field author: Id;
      field category: Id;
      field title: Name;
      field content: Text;
      field state: PostState;
      field likes: Count;
      field createdAt: Moment;
    }

    input CreatePostInput {
      field categoryId: Id;
      field title: Name where length(1, 100);
      field content: Text;
    }

    input FeedInput {
      field keyword: Optional<Text>;
      field page: PageNo;
      field size: PageSize;
    }

    input PostsByTagInput {
      field tagId: Id;
      field page: PageNo;
      field size: PageSize;
    }

    input AttachTagInput {
      field postId: Id;
      field tagId: Id;
    }

    error AlreadyLiked http 409;
    error BadPage http 400;
    error Forbidden http 403;
    error NotPublishable http 409;
    error PostNotFound http 404;
    error TagAttached http 409;
    error TagNotFound http 404;

    capability CreatePost {
      actor Ref<User>;
      input CreatePostInput;
      output PostView;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/myposts";
      workflow {
        validate input.title != "" else Forbidden;
        create Post as made {
          author: actor;
          category: input.categoryId;
          title: input.title;
          content: input.content;
          state: PostState.DRAFT;
          likes: 0;
          createdAt: now();
        }
        persist made;
        return made;
      }
    }

    capability Publish {
      actor Ref<User>;
      input PublishInput;
      output PostView;
      fails Forbidden;
      fails NotPublishable;
      fails PostNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/my/posts/{id}/publish";
      workflow {
        load Post by input.id as found else PostNotFound;
        validate found.author == actor else Forbidden;
        update found when found.state == PostState.DRAFT else NotPublishable {
          state: PostState.PUBLISHED;
        }
        persist found;
        return found;
      }
    }

    capability Feed {
      input FeedInput;
      output Page<PublicPost>;
      fails BadPage;
      requires readonly;
      expose query at "/posts";
      workflow {
        find Post where item.state == PostState.PUBLISHED and (input.keyword is none or item.title containsLiteral input.keyword or item.content containsLiteral input.keyword) order by createdAt descending, id descending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability ViewPost {
      input ViewPostInput;
      output PublicPost;
      fails PostNotFound;
      requires readonly;
      expose query at "/posts/{id}";
      workflow {
        load Post by input.id as found else PostNotFound;
        validate found.state == PostState.PUBLISHED else PostNotFound;
        return found;
      }
    }

    capability AttachTag {
      actor Ref<User>;
      input AttachTagInput;
      output Unit;
      fails Forbidden;
      fails PostNotFound;
      fails TagAttached;
      fails TagNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/posts/{postId}/tags";
      workflow {
        load Post by input.postId as found for update else PostNotFound;
        validate found.author == actor else Forbidden;
        load Tag by input.tagId as tag else TagNotFound;
        exists PostTag where post == found and tag == tag as bound;
        validate not bound else TagAttached;
        create PostTag as made {
          post: found;
          tag: tag;
        }
        persist made;
        return unit;
      }
    }

    capability PostsByTag {
      input PostsByTagInput;
      output Page<PublicPost>;
      fails BadPage;
      fails TagNotFound;
      requires readonly;
      expose query at "/tags/{tagId}/posts";
      workflow {
        load Tag by input.tagId as tag else TagNotFound;
        find Post where item.state == PostState.PUBLISHED and any(PostTag, post == item and tag == tag) order by createdAt descending, id descending Page input.page, input.size else BadPage as rows;
        return rows;
      }
    }

    capability LikePost {
      actor Ref<User>;
      input LikePostInput;
      output PublicPost;
      fails AlreadyLiked;
      fails PostNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/posts/{id}/like";
      workflow {
        load Post by input.id as found for update else PostNotFound;
        validate found.state == PostState.PUBLISHED else PostNotFound;
        exists Like where post == found and user == actor as liked;
        validate not liked else AlreadyLiked;
        create Like as made {
          post: found;
          user: actor;
        }
        persist made;
        update found {
          likes: found.likes + 1;
        }
        persist found;
        return found;
      }
    }
  }
}
